version.transform:
(

$chart := $executeFlow("modeEventGanttChartDataFromWorkcenterHistory",{
  "workcenterId": workcenterId,
  "start": start,
  "end": end
});
{
  "chart": {
    "theme": "fusion",
    "caption": $chart.caption,
    "dateformat": "dd/mm/yyyy hh:mm:ss",
    "outputdateformat": "ddds mns yy",
    "ganttwidthpercent": "60",
    "ganttPaneDuration": "40",
    "ganttPaneDurationUnit": "d",
    "plottooltext": "$processName{br} $label starting date $start{br}$label ending date $end",
    "legendBorderAlpha": "0",
    "legendShadow": "0",
    "usePlotGradientColor": "0",
    "showCanvasBorder": "0",
    "flatScrollBars": "1",
    "gridbordercolor": "#333333",
    "gridborderalpha": "20",
    "slackFillColor": "#e44a00",
    "taskBarFillMix": "light+0",
    "showLegend":1
  },
  "categories": [
    {
      "bgcolor": "#999999",
      "align": "middle",
      "fontcolor": "#ffffff",
      "fontsize": "10",
      "category": $chart.category
    }
  ],
  "processes": {
    "fontcolor": "#000000",
    "fontsize": "11",
    "isanimated": "1",
    "bgcolor": "#6baa01",
    "headervalign": "bottom",
    "headeralign": "left",
    "headerbgcolor": "#999999",
    "headerfontcolor": "#ffffff",
    "headerfontsize": "12",
    "align": "left",
    "isbold": "1",
    "bgalpha": "25",
    "process":[{
          "label": "",
          "id": "1"
        }]
  },
  "tasks": {
    "task": [$chart.task]
  },
  "legend": $chart.legend,
   "milestones": {
        "milestone":[$chart.milestone]
        }
}
)
